    const rows = await open(['# H', '', '- one', '    - two', ''].join('\n'));
    expect(at(rows, 3).column - at(rows, 2).column).toBe(UNIT);
    expect(at(rows, 3).markerX).toBeCloseTo(at(rows, 3).column, 1);
