import { browser, expect } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

function probe(): Promise<unknown> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    if (!view) throw new Error('no active markdown view');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view.editor as any).cm;
    const content: HTMLElement = cm.contentDOM;
    const cb = content.getBoundingClientRect();
    const remPx = parseFloat(getComputedStyle(document.documentElement).fontSize);
    const out: unknown[] = [];
    for (const child of Array.from(content.children)) {
      const el = child as HTMLElement;
      let n = -1;
      try {
        n = cm.state.doc.lineAt(cm.posAtDOM(el)).number - 1;
      } catch {
        n = -99;
      }
      const es = getComputedStyle(el);
      const bullet = el.querySelector(':scope .list-bullet');
      let markerX: number | null = null;
      if (bullet) {
        const after = getComputedStyle(bullet, '::after');
        const br = bullet.getBoundingClientRect();
        markerX = +(
          br.left - cb.left + (parseFloat(after.left) || 0) + (parseFloat(after.width) || 0) / 2
        ).toFixed(2);
      }
      out.push({
        n,
        cls: el.className,
        depth: es.getPropertyValue('--to-depth').trim(),
        markerX,
        boxLeft: +(el.getBoundingClientRect().left - cb.left).toFixed(2),
      });
    }
    const probeEl = document.createElement('div');
    probeEl.style.cssText = 'position:absolute;visibility:hidden;height:0;';
    probeEl.style.width = 'var(--to-decor-unit)';
    document.body.appendChild(probeEl);
    const unit = probeEl.getBoundingClientRect().width;
    probeEl.remove();
    return {
      rem: remPx,
      unit,
      checkbox: getComputedStyle(document.body).getPropertyValue('--checkbox-size'),
      file: view.file?.path,
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      isOutline: (app as any).plugins.plugins['true-outliner']
        ? 'n/a'
        : 'n/a',
      rows: out,
    };
  });
}

describe('diagnose', function () {
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await h.pinPositionIndicatorsOff();
