      it(`indent=${JSON.stringify(indent)} mode=${mode}`, async function () {
        const md = ['# H', '', '- one', `${indent}- two`, `${indent}${indent}- three`, ''].join('\n');
        const note = `Scratch/diag-${Math.random().toString(36).slice(2, 8)}.md`;
        await h.createNote(note, md);
        const on = await h.isOutlineMode(note);
        if ((mode === 'on') !== on) {
          await h.toggleOutlineMode();
          await browser.pause(200);
          await h.dismissNotices();
        }
        await browser.pause(300);
        console.log(`[DIAG] indent=${JSON.stringify(indent)} mode=${mode}`, JSON.stringify(await probe(), null, 1));
        expect(true).toBe(true);
      });
    }
  }
});
