import { browser, expect } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

/** Poll in-page until line 2 carries --to-depth; report how long it took. */
function settleLatency(timeoutMs: number): Promise<{ ms: number; depth: string; tries: number }> {
  return browser.executeObsidian(async ({ app, obsidian }, timeoutMs: number) => {
    const t0 = performance.now();
    let tries = 0;
    for (;;) {
      tries++;
      const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const cm = (view?.editor as any)?.cm;
      let depth = '';
      if (cm) {
        for (const child of Array.from(cm.contentDOM.children) as HTMLElement[]) {
          let n = -1;
          try {
            n = cm.state.doc.lineAt(cm.posAtDOM(child)).number - 1;
          } catch {
            continue;
          }
          if (n === 2) {
            depth = getComputedStyle(child).getPropertyValue('--to-depth').trim();
            break;
          }
        }
      }
      const ms = performance.now() - t0;
      if (depth !== '' || ms > timeoutMs) return { ms: +ms.toFixed(1), depth, tries };
      await new Promise((r) => setTimeout(r, 5));
    }
  }, timeoutMs);
}

describe('diagnose settle latency', function () {
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await h.pinPositionIndicatorsOff();
  });

  it('measures how long the toggle takes to reach the DOM, many times', async function () {
    this.timeout(600_000);
    const md = ['# H', '', '- one', `   - two`, `      - three`, ''].join('\n');
    const samples: Array<{ ms: number; depth: string; tries: number }> = [];
    for (let i = 0; i < 40; i++) {
      const note = `Scratch/diag-${i}.md`;
      await h.createNote(note, md);
      const on = await h.isOutlineMode(note);
      if (!on) await h.toggleOutlineMode();
      samples.push(await settleLatency(3000));
      await h.dismissNotices();
    }
    const bad = samples.filter((s) => s.depth === '');
    console.log('[DIAG] settle ms:', JSON.stringify(samples.map((s) => s.ms)));
    console.log('[DIAG] never settled:', bad.length, 'of', samples.length);
    console.log('[DIAG] max:', Math.max(...samples.map((s) => s.ms)));
    expect(true).toBe(true);
  });
});
