import { browser, expect } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

describe('toggle latency', function () {
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
    await h.pinPositionIndicatorsOff();
  });

  it('times saveData and the command-to-decoration gap', async function () {
    this.timeout(600_000);
    const md = ['# H', '', '- one', '   - two', '      - three', ''].join('\n');
    const saves: number[] = [];
    const gaps: number[] = [];
    for (let i = 0; i < 25; i++) {
      const note = `Scratch/lat-${i}.md`;
      await h.createNote(note, md);
      const r = await browser.executeObsidian(async ({ app, obsidian, plugins }) => {
        const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const cm = (view.editor as any).cm;
        const lineEl = (): HTMLElement | null => {
          for (const child of Array.from(cm.contentDOM.children) as HTMLElement[]) {
            try {
              if (cm.state.doc.lineAt(cm.posAtDOM(child)).number - 1 === 2) return child;
            } catch {
              /* not a mapped child */
            }
          }
          return null;
        };
        const decorated = (): boolean =>
          (lineEl()?.style.getPropertyValue('--to-depth') ?? '') !== '';

        const t0 = performance.now();
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (app as any).commands.executeCommandById('true-outliner:toggle-outline-mode');
        while (!decorated() && performance.now() - t0 < 5000) {
          await new Promise((r) => requestAnimationFrame(() => r(null)));
        }
        const gap = performance.now() - t0;

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const plugin = plugins.trueOutliner as any;
        const t1 = performance.now();
        await plugin.saveData(plugin.data);
        const save = performance.now() - t1;
        return { gap: +gap.toFixed(1), save: +save.toFixed(1) };
      });
      gaps.push(r.gap);
      saves.push(r.save);
      await h.dismissNotices();
    }
    const stat = (xs: number[]) => {
      const s = [...xs].sort((a, b) => a - b);
      return { min: s[0], p50: s[Math.floor(s.length / 2)], max: s[s.length - 1] };
    };
    console.log('[LAT] command->decoration gap ms:', JSON.stringify(gaps));
    console.log('[LAT] gap stats:', JSON.stringify(stat(gaps)));
    console.log('[LAT] saveData ms:', JSON.stringify(saves));
    console.log('[LAT] save stats:', JSON.stringify(stat(saves)));
    expect(true).toBe(true);
  });
});
