import { browser, expect } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

/** Make the plugin's data write take `ms`, the way a contended disk does. */
function slowSaves(ms: number): Promise<void> {
  return browser.executeObsidian(({ plugins }, ms: number) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const plugin = plugins.trueOutliner as any;
    if (!plugin.__origSaveData) plugin.__origSaveData = plugin.saveData.bind(plugin);
    plugin.saveData = async (data: unknown) => {
      await new Promise((r) => setTimeout(r, ms));
      return plugin.__origSaveData(data);
    };
  }, ms);
}

function markerAndDepth(): Promise<{ depth: string; markerX: number | null } | null> {
  return browser.executeObsidian(({ app, obsidian }) => {
    const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cm = (view?.editor as any)?.cm;
    if (!cm) return null;
    const cb = cm.contentDOM.getBoundingClientRect();
    for (const child of Array.from(cm.contentDOM.children) as HTMLElement[]) {
      try {
        if (cm.state.doc.lineAt(cm.posAtDOM(child)).number - 1 !== 2) continue;
      } catch {
        continue;
      }
      const bullet = child.querySelector(':scope .list-bullet');
      let markerX: number | null = null;
      if (bullet) {
        const after = getComputedStyle(bullet, '::after');
        const br = bullet.getBoundingClientRect();
        markerX = +(
          br.left - cb.left + (parseFloat(after.left) || 0) + (parseFloat(after.width) || 0) / 2
        ).toFixed(2);
      }
      return { depth: getComputedStyle(child).getPropertyValue('--to-depth').trim(), markerX };
    }
    return null;
  });
}

