it('paints the note in the command\u2019s own turn, not after the data write', async function () {
  // The gap this closes: a mode toggle dispatches no transaction of its own,
  // so the decorations only recompute when the plugin nudges the editor \u2014
  // and that nudge used to sit behind the awaited `data.json` write. The
  // whole note stayed stock-rendered for however long the disk took.
  //
  // Measured with the write slowed to 900ms: `--to-depth` was absent and the
  // bullet sat on Obsidian's own native column, which is the state
  // 56-list-grid reported from CI as a marker one gutter off its depth-0
  // column. Under real load a plain `saveData` reached 754ms on a fast
  // machine, so the suite's fixed settle pauses were a wager on disk latency.
  //
  // Asserted in ONE synchronous turn rather than after a settle: the point is
  // not that the paint arrives eventually \u2014 it always did \u2014 but that nothing
  // asynchronous stands between the command and it. A poll would pass on the
  // old code as soon as the write landed.
  await h.createNote('Scratch/paints-now.md', ['# H', '', '- one', ''].join('\n'));
  const decorated = await browser.executeObsidian(({ app, obsidian }) => {
